import { Component, computed, input, model, output, ChangeDetectionStrategy } from '@angular/core';
import { ButtonModule } from 'primeng/button';
import { DialogModule } from 'primeng/dialog';

export type TipoConfirmacion = 'success' | 'error' | 'warning';

@Component({
  selector: 'tpp-confirmation-modal',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DialogModule, ButtonModule],
  templateUrl: './confirmation-modal.component.html',
  styles: ``,
})
export class ConfirmationModalComponent {
  configuracion = computed(() => this.tipoConfig[this.tipo()] ?? this.tipoConfig.success);

  titulo = input('');
  mensaje = input('');
  tipo = input<TipoConfirmacion>('success');
  labelCancelar = input('Cancelar');
  labelConfirmar = input('Confirmar');
  labelConfirmarCargando = input('Confirmando');
  procesando = input(false);

  confirmado = output<void>();
  cancelado = output<void>();

  visible = model(false);

  confirmar() {
    this.confirmado.emit();
  }

  cancelar() {
    this.cancelado.emit();
    this.visible.set(false);
  }

  private readonly tipoConfig: Record<TipoConfirmacion, { iconoBg: string; iconoColor: string; icono: string }> = {
    success: { iconoBg: 'bg-green-50',   iconoColor: 'text-green-600',  icono: 'ti ti-circle-check'   },
    error:   { iconoBg: 'bg-red-50',     iconoColor: 'text-red-600',    icono: 'ti ti-cancel'       },
    warning: { iconoBg: 'bg-yellow-50',  iconoColor: 'text-yellow-600', icono: 'ti ti-alert-triangle' },
  };
}
