import { CommonModule } from '@angular/common';
import { Component, Input, ViewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { AutoComplete, AutoCompleteModule } from 'primeng/autocomplete';
import { ButtonModule } from 'primeng/button';
import { IconFieldModule } from 'primeng/iconfield';
import { InputIconModule } from 'primeng/inputicon';

interface AutoCompleteCompleteEvent {
  originalEvent: Event;
  query: string;
}

@Component({
  selector: 'tpp-search',
  imports: [
    CommonModule,
    FormsModule,
    ButtonModule,
    AutoCompleteModule,
    IconFieldModule,
    InputIconModule
  ],
  templateUrl: './search.component.html',
  styleUrl: './search.component.css'
})
export class SearchComponent {

  items: any[] = [];
  value: any;
  buscadorVisible = false;
  @Input() placeholder: string = 'Buscar';
  @ViewChild('autocompleteRef') autocompleteRef!: AutoComplete;

  buscar(event: AutoCompleteCompleteEvent) {
      this.items = [...Array(10).keys()].map(item => event.query + '-' + item);
  }

  alternarBusqueda() {
    this.buscadorVisible = !this.buscadorVisible;
    if (this.buscadorVisible) {
      setTimeout(() => this.autocompleteRef?.inputEL?.nativeElement?.focus());
    }
  }

}
