import { Component, effect, input, model, signal, ChangeDetectionStrategy } from '@angular/core';
import { DialogModule } from 'primeng/dialog';
import { LoadingStateComponent } from '../loading-state/loading-state.component';

@Component({
  selector: 'tpp-video-tutorial-modal',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DialogModule, LoadingStateComponent],
  templateUrl: './video-tutorial-modal.component.html',
  styles: ``,
})
export class VideoTutorialModalComponent {
  url = input.required<string>();
  visible = model(false);
  cargandoVideo = signal(true);

  constructor() {
    effect(() => {
      if (this.visible()) {
        this.cargandoVideo.set(true);
        setTimeout(() => {
          this.cargandoVideo.set(false);
        }, 2000);
      }
    });
  }
}
